function sobelGrid(px, w, h) {
  const out = new Float32Array(w * h * 2);
  for (let y = 1; y < h - 1; y++) {
    for (let x = 1; x < w - 1; x++) {
      const i = (x + y * w) * 4;
      const tl=px[i-4-w*4], t=px[i-w*4], tr=px[i+4-w*4];
      const l =px[i-4],                  r =px[i+4];
      const bl=px[i-4+w*4], b=px[i+w*4], br=px[i+4+w*4];
      const k = (x + y * w) * 2;
      out[k]   = -tl - 2*l - bl + tr + 2*r + br;  // Gx
      out[k+1] = -tl - 2*t - tr + bl + 2*b + br;  // Gy
    }
  }
  return out;
}

// Floyd-Steinberg Dithering
for (let y = 0; y < height; y++) {
  for (let x = 0; x < width; x++) {
    const i = y * width + x;
    const oldPixel = gs[i];
    const newPixel = oldPixel < threshold ? 0 : 255;
    const quantError = oldPixel - newPixel;
    gs[i] = newPixel;
    if (x+1 < width)   gs[i+1]       += quantError * 7/16;
    if (x-1 >= 0 && y+1 < height)
                       gs[i-1+width] += quantError * 3/16;
    if (y+1 < height)  gs[i+width]   += quantError * 5/16;
    if (x+1 < width && y+1 < height)
                       gs[i+1+width] += quantError * 1/16;
  }
}

// Conway's Game of Life
for (let i = 0; i < count; i++) {
  for (let j = 0; j < count; j++) {
    let liveNeighbors = 0;
    for (let x = -1; x <= 1; x++) {
      for (let y = -1; y <= 1; y++) {
        if (x === 0 && y === 0) continue;
        const ni = (i + x + count) % count;
        const nj = (j + y + count) % count;
        if (grid[ni][nj] === 1) liveNeighbors++;
      }
    }
    const state = grid[i][j];
    // B3/S23: Birth at 3, Survive at 2-3
    if (state === 1)
      newGrid[i][j] = [2,3].includes(liveNeighbors) ? 1 : 0;
    else
      newGrid[i][j] = liveNeighbors === 3 ? 1 : 0;
  }
}
